import logging
from taf.converters.base import ConverterComponent
from taf.internal.managedobject import ManagedObject
from pathlib import Path
from abc import abstractmethod
import json
import csv
import io

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class EmilConverterBase(ManagedObject, ConverterComponent):
    def __init__(self,
                 name,
                 finder,
                 decoding_strategy,
                 server_filter=None,
                 client_filter=None,
                 output_directory=None,
                 dcap_connection=None,
                 uploading_timeout=None,
                 decoding_timeout=300,
                 **kwargs):
        super(EmilConverterBase, self).__init__(**kwargs)

        self._name = name
        self._dcap_connection = dcap_connection
        self._finder = finder
        self._input_files = []
        self._output_directory = output_directory
        self._uploading_params = {'timeout': uploading_timeout} if uploading_timeout else {}
        self._decoding_strategy = decoding_strategy
        self._client_filter = client_filter if client_filter else lambda x: True
        self._decoding_params = {key: value for key, value in {
            'filter': server_filter,
            'timeout': decoding_timeout}.items() if value is not None}

    def _setup(self):
        try:
            self._dcap_connection.get_encoded_files_info()
        except Exception as error:
            if error.status == 404:
                raise Exception("Emil JSON server is not enabled in DCAP setup provided. "
                                "please refer the docs on installation of EMIL JSON server.")
        self._input_files = list(self._finder.find())
        self._output_directory = self._output_directory \
            if self._output_directory else Path(self._input_files[0]).parent

    def convert(self):
        upload_response = self._upload_files()
        data_source_range = self._get_data_source_range(upload_response)
        dest_files = self._get_dest_files(data_source_range)

        for data_source, dest_file in zip(data_source_range, dest_files):
            self._get_decoding_responses_and_write(upload_response, data_source, dest_file)

    def _get_data_source_range(self, upload_response):
        return set(getattr(upload_response, self._range_name))

    def _get_dest_files(self, data_source_range):
        return [Path(self._output_directory).joinpath(
            f'{data_source}_{self._what}{self._decoding_strategy.file_extension}')
            for data_source in data_source_range]

    def _get_decoding_responses_and_write(self, upload_response, data_source_id, dest_file):
        with self._open_file_for_writing(dest_file) as file_descriptor:
            self._decoding_strategy.get_decoding_responses_and_write(
                dcap_connection=self._dcap_connection,
                file_descriptor=file_descriptor,
                client_filter=self._client_filter,
                session_id=upload_response.session_id,
                what=self._what,
                data_source_id=data_source_id,
                **self._decoding_params)

    def _upload_files(self):
        upload_response = self._dcap_connection.upload_encoded_file(
            file_name=self._input_files,
            **self._uploading_params)
        return upload_response

    @staticmethod
    def _open_file_for_writing(file_name):
        Path(file_name).parent.mkdir(parents=True, exist_ok=True)
        return open(file_name, 'w')

    def _teardown(self):
        self._dcap_connection = None


class EmilConverterForSource(EmilConverterBase):

    _what = 'source'
    _range_name = 'source_ids'


class EmilConverterForCalls(EmilConverterBase):

    _what = 'calls'
    _range_name = 'grid_ids'


class EmilConverterForCall(EmilConverterBase):

    _range_name = 'grid_ids'

    def __init__(self, trace_id,  **kwargs):
        super(EmilConverterForCall, self).__init__(**kwargs)
        self._what = str(trace_id)


class OutputStrategy(object):

    _batch_size = 1000

    @staticmethod
    def row_range(start_row, batch_size):
        return f'{start_row}-{start_row + batch_size-1}'

    def get_decoding_responses_and_write(self,
                                         dcap_connection,
                                         file_descriptor,
                                         client_filter,
                                         **kwargs):
        batch_size = self._batch_size
        decoded_response = getattr(dcap_connection, self._get_decoded_file_contents)(
            rows=self.row_range(0, batch_size+1),
            **kwargs)
        last_row = batch_size
        self.write_response_after_filter(
            client_filter, file_descriptor, decoded_response, write_header=True)
        while True:
            decoded_response = getattr(dcap_connection, self._get_decoded_file_contents)(
                rows=self.row_range(last_row+1, batch_size),
                **kwargs)
            if self.is_empty(decoded_response):
                break
            self.write_response_after_filter(
                client_filter, file_descriptor, decoded_response)
            last_row += batch_size

    @staticmethod
    @abstractmethod
    def write_response_after_filter(client_filter,
                                    file_descriptor,
                                    response,
                                    write_header=False):
        pass

    @staticmethod
    @abstractmethod
    def is_empty(decoded_response):
        pass

    @property
    def file_extension(self):
        return self._file_extension


class JsonOutputStrategy(OutputStrategy):

    _file_extension = '.json'
    _get_decoded_file_contents = 'get_decoded_file_contents_in_json'

    @staticmethod
    def is_empty(decoded_response):
        return not bool(decoded_response.to_dict()['emil_data']['rows'])

    @staticmethod
    def write_response_after_filter(client_filter,
                                    file_descriptor,
                                    response,
                                    write_header=False):
        if output := '\n'.join([
            json.dumps(row)
            for row in response.to_dict()['emil_data']['rows']
                if client_filter(row)]):
            file_descriptor.write(output + '\n')


class CsvOutputStrategy(OutputStrategy):

    _file_extension = '.csv'
    _get_decoded_file_contents = 'get_decoded_file_contents_in_csv'

    @staticmethod
    def is_empty(decoded_response):
        return not bool(decoded_response.split("\n", 1)[1])

    @staticmethod
    def write_response_after_filter(client_filter,
                                    file_descriptor,
                                    response,
                                    write_header=False):
        csv_reader = csv.DictReader(
            io.StringIO(response),
            fieldnames=None,
            delimiter=";")
        writer = csv.DictWriter(file_descriptor,
                                fieldnames=csv_reader.fieldnames,
                                delimiter=';')
        if write_header:
            writer.writeheader()
        for row in csv_reader:
            if client_filter(row):
                writer.writerow(row)
